import type { Room, Seat } from '../../core/index.js';

export interface NeighborSet {
  horizontal: Seat[];
  vertical: Seat[];
  diagonal: Seat[];
}

/**
 * Physical seat adjacency graph for one room. Seats are addressed by their
 * explicit (row, col) coordinates rather than array position, so irregular
 * row lengths and gaps (blocked/missing seats) are handled correctly instead
 * of assuming a rectangular grid.
 *
 * Assumption (documented default, spec is silent on alignment): rows are
 * left-aligned starting at column 1, so a seat's `col` is its physical
 * horizontal position and vertical/diagonal neighbors are found by matching
 * column number in the adjacent row.
 */
export class SeatGraph {
  readonly roomId: string;
  readonly seatsById: Map<string, Seat>;
  private readonly byCoord: Map<string, Seat>;
  private readonly neighborCache = new Map<string, NeighborSet>();

  constructor(room: Room) {
    this.roomId = room.id;
    this.seatsById = new Map(room.seats.map((s) => [s.id, s]));
    this.byCoord = new Map(room.seats.map((s) => [coordKey(s.row, s.col), s]));
  }

  private at(row: number, col: number): Seat | undefined {
    return this.byCoord.get(coordKey(row, col));
  }

  neighborsOf(seat: Seat): NeighborSet {
    const cached = this.neighborCache.get(seat.id);
    if (cached) return cached;

    const horizontal: Seat[] = [];
    const left = this.at(seat.row, seat.col - 1);
    const right = this.at(seat.row, seat.col + 1);
    if (left) horizontal.push(left);
    if (right) horizontal.push(right);

    const vertical: Seat[] = [];
    const up = this.at(seat.row - 1, seat.col);
    const down = this.at(seat.row + 1, seat.col);
    if (up) vertical.push(up);
    if (down) vertical.push(down);

    const diagonal: Seat[] = [];
    for (const [dr, dc] of [
      [-1, -1],
      [-1, 1],
      [1, -1],
      [1, 1],
    ] as const) {
      const s = this.at(seat.row + dr, seat.col + dc);
      if (s) diagonal.push(s);
    }

    const set: NeighborSet = { horizontal, vertical, diagonal };
    this.neighborCache.set(seat.id, set);
    return set;
  }

  /** Manhattan-ish physical distance, used for roll-continuity scoring. */
  distance(a: Seat, b: Seat): number {
    return Math.abs(a.row - b.row) + Math.abs(a.col - b.col);
  }
}

function coordKey(row: number, col: number): string {
  return `${row}:${col}`;
}

export function buildSeatGraphs(rooms: Room[]): Map<string, SeatGraph> {
  const map = new Map<string, SeatGraph>();
  for (const room of rooms) {
    map.set(room.id, new SeatGraph(room));
  }
  return map;
}
